@page {
  size: A4;
  margin: 10mm 8mm 10mm 8mm;  /* top right bottom left */
}

html, body {
  margin: 0;
  padding: 0;
}

.page {
  width: 180mm;              /* <= less than 210mm page width */
  margin: 0 auto;            /* center on page */
  page-break-after: always;  /* one .page per PDF page */
}

body {
  font-family: 'Ubuntu', sans-serif;
}

.header-section, .footer-section {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.header-section {
  border-bottom: 1px solid #ccc;
  display: table;
  width: 100%;
}

.header-section .logo-container {
  display: table-cell;
  width: 25%;
  vertical-align: middle;
}

.footer-section {
    flex-direction: row-reverse;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 12px;
    color: hsl(0, 0%, 27%);
    margin-top: 10px;
  /*border-top: 1px solid #ccc;*/
  /*font-size: 12px;*/
  /*color: #444;*/
  /*position: relative;*/
  /*bottom: 0;*/
  /*margin-top: 55px;*/
}
  .footer-section .ar {
    direction: rtl;
    text-align: right;
    flex: 1;
  }
  .footer-section .en {
    direction: ltr;
    text-align: left;
    flex: 1;
  }






.logo {
  width: 110px;
  height: auto;
}

.company-names 

{
  text-align: right;
  display: table-cell;
  width: 75%;
  text-align: right;
  vertical-align: middle;
}

.company-names .en {
  margin: 0;
  font-size: 16px;
  font-family:'Roboto', sans-serif;
  color: #000;
}

.company-names .ar {
  margin: 0;
  font-size: 22px;
  font-family:'Cascadia Mono', monospace;
  font-weight: 500;
  color: #000;
  direction: rtl;
}

