.page-content {
  padding: 8mm 5mm;
  font-size: 14px;
  line-height: 1.4;
}

.page-tc-content {
  font-family:'Noto Naskh Arabic', serif;
  padding: 8mm 5mm;
  font-size: 12px;
  line-height: 2;
  direction: rtl;
  text-align: right;
}

.tc-heading {
  font-size: 22px;
  font-family: 'Noto Naskh Arabic', serif;
}

.part {
  font-size: 14px;
  font-family: 'Noto Naskh Arabic', serif;
}

table {
  border-collapse: collapse;
  width: 100%;
  table-layout: fixed;
}

.table.table-bordered 
th {
  font-family : 'Ubuntu';
  border: 0px solid #aaa;
  text-align: left;
  background-color: #efdfdf;
  font-weight: 300;
  color:#07417b;
}
img.qr {
  max-width: 100px !important;
  max-height: 100px !important;
  width: 100px !important;
  height: auto !important;
  object-fit: contain !important;
  display: block;
  margin: 0 auto;
}
table td, table th {
  padding: 4px 6px;
  vertical-align: top;     /* prevents row expansion */
  line-height: 1.3;
}

td {
  padding: 6px;
  text-align: left;
  font-family : 'Ubuntu','Cairo';
  font-size: 14px;
}
.qr-cell {
  width: 130px !important;     /* avoid auto-stretch */
  vertical-align: middle !important;
  text-align: center !important;
}
